create or replace function apply_kpi_target_status()returns trigger language plpgsql security definer set search_path=public as $$declare t kpi_targets%rowtype;dir text;begin
select direction into dir from kpi_definitions where id=new.kpi_definition_id;
select*into t from kpi_targets where organization_id=new.organization_id and kpi_definition_id=new.kpi_definition_id and(production_area_id is null or production_area_id=new.production_area_id)and(shift_id is null or shift_id=new.shift_id)and effective_from<=new.production_date and(effective_to is null or effective_to>=new.production_date)order by(production_area_id is not null)desc,(shift_id is not null)desc,effective_from desc limit 1;
if new.value is null then new.status='NO_DATA';new.target_value=null;return new;end if;if t.id is null then new.status='NO_TARGET';new.target_value=null;return new;end if;new.target_value=t.target_value;
if dir='HIGHER_IS_BETTER'then new.status=case when new.value>=t.target_value then'GOOD'when t.warning_value is not null and new.value>=t.warning_value then'WARNING'else'CRITICAL'end;elsif dir='LOWER_IS_BETTER'then new.status=case when new.value<=t.target_value then'GOOD'when t.warning_value is not null and new.value<=t.warning_value then'WARNING'else'CRITICAL'end;else new.status=case when t.critical_value is not null and abs(new.value-t.target_value)>t.critical_value then'CRITICAL'when t.warning_value is not null and abs(new.value-t.target_value)>t.warning_value then'WARNING'else'GOOD'end;end if;return new;end$$;
drop trigger if exists kpi_result_target_status on kpi_results;create trigger kpi_result_target_status before insert on kpi_results for each row execute function apply_kpi_target_status();
